select case when year(s.opened_date) < 2024 then 'before_2024' when year(s.opened_date) = 2024 then '2024' else 'after_2024' end as opened_cohort, sum(ss.revenue) as total_revenue, min(ss.units) as min_units from store_sales ss join products p on ss.product_id = p.id left join stores s on ss.store_id = s.id group by case when year(s.opened_date) < 2024 then 'before_2024' when year(s.opened_date) = 2024 then '2024' else 'after_2024' end order by 2 desc;
